mapper.select:
SELECT c.id, c.credential_group_id, c.previous_credential_id, c.credential_no, c.version_no, c.issuer_identifier, c.subject_identifier, c.credential_type, c.status, c.valid_from, c.valid_until, c.vc_payload, c.vc_hash, c.chain_key, c.vc_hash_version, c.issued_at, c.revoked_at, c.revocation_reason, c.failure_code, c.failure_message, c.created_at, c.updated_at FROM tb_credentials c JOIN tb_credential_groups g ON g.id = c.credential_group_id JOIN tb_completions completion ON completion.id = g.completion_id JOIN tb_enrollments enrollment ON enrollment.id = completion.enrollment_id WHERE enrollment.user_id = #{userId} ORDER BY
c.issued_at c.updated_at c.created_at
ASC DESC , c.id ASC LIMIT #{limit} OFFSET #{offset}
